<?php
$root=$argv[1];if(getenv('FIXTURE_URL')!=='http://127.0.0.1:9440')throw new RuntimeException('Owned independent fixture required');$_SERVER['HTTP_HOST']='127.0.0.1:9440';require $root.'/wp-load.php';wp_set_current_user(1);
if(get_stylesheet()!=='twentytwentyfour'||get_option('home')!=='http://127.0.0.1:9440'||!function_exists('tribe_create_event'))throw new RuntimeException('Unexpected fixture');
$receipt=dirname($root).'/independent-event-records.json';if(file_exists($receipt))throw new RuntimeException('Independent definitions are immutable after seeding');
foreach(get_posts(['post_type'=>['tribe_events','tribe_venue'],'post_status'=>'any','numberposts'=>-1]) as $post)wp_delete_post($post->ID,true);
$venue=tribe_create_venue(['Venue'=>'Harbor Studio','Address'=>'28 Coast Road','City'=>'Sample Bay','State'=>'California','Country'=>'United States','Zip'=>'94000']);
$definitions=[['Coastal Design Lab','2028-03-11 10:00:00','2028-03-13 12:00:00',false,'America/Los_Angeles'],['Open Studio Day','2028-06-17 00:00:00','2028-06-17 23:59:59',true,'America/Los_Angeles'],['Morning Gathering','2028-10-29 10:00:00','2028-10-29 11:00:00',false,'Europe/London'],['Summer Residency','2028-07-31 00:00:00','2028-08-02 23:59:59',true,'America/Los_Angeles']];$records=[];
foreach($definitions as $d){$id=tribe_create_event(['post_title'=>$d[0],'post_status'=>'publish','post_content'=>'<p>Explore materials and local creative work in this independent calendar fixture. No bookings or payments are accepted.</p>','EventStartDate'=>substr($d[1],0,10),'EventStartTime'=>substr($d[1],11),'EventEndDate'=>substr($d[2],0,10),'EventEndTime'=>substr($d[2],11),'EventAllDay'=>$d[3],'EventTimezone'=>$d[4],'EventVenueID'=>$venue,'EventCost'=>'18','EventCurrencySymbol'=>'$']);if(!$id||is_wp_error($id)||!get_post_meta($id,'_EventStartDateUTC',true))throw new RuntimeException('Event creation failed');$records[]=['id'=>$id,'url'=>get_permalink($id),'definition'=>$d];}
flush_rewrite_rules();file_put_contents($receipt,json_encode(['events'=>$records,'venue'=>$venue],JSON_PRETTY_PRINT));echo 'Seeded '.count($records)." independent events\n";
